import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
export function showEfficiency(kind,t=null,value=null){const yieldMode=kind==='yield';
 const title=yieldMode?'Possible → collected':'Reactants → desired product';
 let body=yieldMode?`<div class="inventory-row"><span>Theoretical maximum · ${t?.theoretical??10} g</span><small>Actual collected · ${t?.actual??8} g</small></div>`:`<div class="inventory-row"><span>Desired product · ${t?.desired??'CaO'}</span><small>${t?t.names.map((n,i)=>n+': '+t.mrs[i]).join(' · '):'Use the balanced equation and relative masses'}</small></div>`;
 body+=value===null?'<p class="inventory-outcome">Predict the percentage before revealing the comparison.</p>':`<p class="inventory-outcome">${yieldMode?'Percentage yield':'Atom economy'} · ${value.toFixed(1)}%</p><div class="efficiency-bar" role="img" aria-label="${value.toFixed(1)} percent ${yieldMode?'collected product':'desired-product mass contribution'}"><i style="width:${Math.min(100,value)}%"></i></div><p class="diagram-caption">${yieldMode?'Light: collected · dark: difference from maximum':'Light: desired product · dark: other products'}</p>`;
 renderDiagram(title,yieldMode?'Actual ÷ theoretical × 100':t?.equation||'CaCO₃ → CaO + CO₂',`<div class="inventory-board"><span class="eyebrow">${yieldMode?'RECOVERY ACCOUNT':'EQUATION MASS ACCOUNT'}</span>${body}<p class="diagram-caption">${yieldMode?'An amount comparison, not an apparatus simulation. Uncollected atoms remain in other material.':'Relative masses include balanced coefficients. This is not an experimental yield.'}</p></div>`,yieldMode?'RECOVERY · SAME MASS UNITS':'ATOM UTILISATION · DESIRED PRODUCT SPECIFIED');}
